#include <iostream>
#include <string>
#include <utility>

void inspect(const std::string&) { std::cout << "borrow\n"; }
void inspect(std::string&&) { std::cout << "rvalue\n"; }

template<class T>
void relay(T&& value)
{
    inspect(std::forward<T>(value));
}

int main()
{
    std::string title{"Atlas"};
    relay(title);
    relay(std::string{"Maps"});
}
